// File: internal/status/status.go
// Purpose: Aggregate gateway health and live collector activity into bounded observable status snapshots.
// Generated by: aiAgentTseiman (Hermes Agent)
// Generated on: 2026-10-13

package status

import (
	"errors"
	"sort"
	"sync"
	"time"

	"github.com/tseiman/HomeAutomationMonitorGW/internal/cache"
)

var (
	ErrTooManySubscribers = errors.New("too many status subscribers")
	ErrClosed             = errors.New("status hub is closed")
)

type Health struct {
	Code  int    `json:"code"`
	State string `json:"state"`
}

type Activity struct {
	Active     bool     `json:"active"`
	Collectors []string `json:"collectors"`
}

type Collector struct {
	Driver      string    `json:"driver,omitempty"`
	Health      string    `json:"health"`
	Available   bool      `json:"available"`
	Stale       bool      `json:"stale"`
	Polling     bool      `json:"polling"`
	LastAttempt time.Time `json:"last_attempt"`
	LastSuccess time.Time `json:"last_success"`
}

type Snapshot struct {
	SchemaVersion int                  `json:"schema_version"`
	Sequence      uint64               `json:"sequence"`
	Timestamp     time.Time            `json:"timestamp"`
	Service       string               `json:"service"`
	Health        Health               `json:"health"`
	Activity      Activity             `json:"activity"`
	Collectors    map[string]Collector `json:"collectors"`
}

type Hub struct {
	store          *cache.Store
	now            func() time.Time
	maxSubscribers int

	mu              sync.Mutex
	sequence        uint64
	active          map[string]int
	healthCodes     map[string]int
	subscribers     map[chan struct{}]struct{}
	monitorStop     chan struct{}
	monitorOnce     sync.Once
	monitorInterval time.Duration
	closed          bool
}

func New(store *cache.Store, now func() time.Time, maxSubscribers int) *Hub {
	return newHub(store, now, maxSubscribers, 250*time.Millisecond)
}

func newHub(store *cache.Store, now func() time.Time, maxSubscribers int, monitorInterval time.Duration) *Hub {
	if now == nil {
		now = time.Now
	}
	if maxSubscribers < 1 {
		maxSubscribers = 1
	}
	if monitorInterval <= 0 {
		monitorInterval = 250 * time.Millisecond
	}
	hub := &Hub{
		store: store, now: now, maxSubscribers: maxSubscribers, sequence: 1, monitorInterval: monitorInterval,
		active: make(map[string]int), subscribers: make(map[chan struct{}]struct{}), monitorStop: make(chan struct{}),
	}
	hub.healthCodes = hub.currentHealthCodesLocked()
	return hub
}

func (h *Hub) PollStarted(name string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		return
	}
	h.active[name]++
	h.healthCodes = h.currentHealthCodesLocked()
	h.notifyLocked()
}

func (h *Hub) PollFinished(name string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed || h.active[name] == 0 {
		return
	}
	h.active[name]--
	if h.active[name] == 0 {
		delete(h.active, name)
	}
	h.healthCodes = h.currentHealthCodesLocked()
	h.notifyLocked()
}

func (h *Hub) Snapshot() Snapshot {
	h.mu.Lock()
	sequence := h.sequence
	active := make(map[string]int, len(h.active))
	for name, count := range h.active {
		active[name] = count
	}
	h.mu.Unlock()

	result := Snapshot{
		SchemaVersion: 1,
		Sequence:      sequence,
		Timestamp:     h.now().UTC(),
		Service:       "running",
		Health:        Health{Code: 2, State: "failed"},
		Activity:      Activity{Collectors: []string{}},
		Collectors:    map[string]Collector{},
	}
	if h.store != nil {
		all := h.store.Statuses()
		if len(all) > 0 {
			result.Health = Health{Code: 0, State: "ok"}
		}
		for _, source := range all {
			health := sourceHealth(source)
			if health.Code > result.Health.Code {
				result.Health = health
			}
			result.Collectors[source.Name] = Collector{
				Driver: source.Driver, Health: health.State, Available: source.Available,
				Stale: source.Stale, Polling: active[source.Name] > 0,
				LastAttempt: source.LastAttempt, LastSuccess: source.LastSuccess,
			}
		}
	}
	for name := range active {
		result.Activity.Collectors = append(result.Activity.Collectors, name)
		if _, exists := result.Collectors[name]; !exists {
			result.Collectors[name] = Collector{Health: "degraded", Polling: true}
			if result.Health.Code < 1 {
				result.Health = Health{Code: 1, State: "degraded"}
			}
		}
	}
	sort.Strings(result.Activity.Collectors)
	result.Activity.Active = len(result.Activity.Collectors) > 0
	return result
}

func sourceHealth(source cache.Snapshot) Health {
	if !source.Available {
		if source.LastAttempt.IsZero() {
			return Health{Code: 1, State: "degraded"}
		}
		return Health{Code: 2, State: "failed"}
	}
	if source.Stale || source.LastSuccess.IsZero() {
		return Health{Code: 1, State: "degraded"}
	}
	return Health{Code: 0, State: "ok"}
}

func (h *Hub) Subscribe() (<-chan struct{}, func(), error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		return nil, nil, ErrClosed
	}
	if len(h.subscribers) >= h.maxSubscribers {
		return nil, nil, ErrTooManySubscribers
	}
	ch := make(chan struct{}, 1)
	h.subscribers[ch] = struct{}{}
	h.monitorOnce.Do(func() { go h.monitorHealth(h.monitorInterval) })
	var once sync.Once
	unsubscribe := func() {
		once.Do(func() {
			h.mu.Lock()
			defer h.mu.Unlock()
			if _, exists := h.subscribers[ch]; exists {
				delete(h.subscribers, ch)
				close(ch)
			}
		})
	}
	return ch, unsubscribe, nil
}

func (h *Hub) Close() {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		return
	}
	h.closed = true
	close(h.monitorStop)
	for ch := range h.subscribers {
		close(ch)
		delete(h.subscribers, ch)
	}
}

func (h *Hub) monitorHealth(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-h.monitorStop:
			return
		case <-ticker.C:
			h.mu.Lock()
			if h.closed {
				h.mu.Unlock()
				return
			}
			current := h.currentHealthCodesLocked()
			if !equalHealthCodes(current, h.healthCodes) {
				h.healthCodes = current
				h.notifyLocked()
			}
			h.mu.Unlock()
		}
	}
}

func (h *Hub) currentHealthCodesLocked() map[string]int {
	codes := make(map[string]int)
	if h.store == nil {
		return codes
	}
	for _, source := range h.store.Statuses() {
		codes[source.Name] = sourceHealth(source).Code
	}
	return codes
}

func equalHealthCodes(left, right map[string]int) bool {
	if len(left) != len(right) {
		return false
	}
	for name, code := range left {
		if other, exists := right[name]; !exists || other != code {
			return false
		}
	}
	return true
}

func (h *Hub) notifyLocked() {
	h.sequence++
	for ch := range h.subscribers {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}
